def find_prefix_len(name, precom):
	used_indexes = [0] * 29
	prefix_len = 0
	for c in name:
		i = ord(c) - ord('a')
		index = precom[i][used_indexes[i]]
		used_indexes[i] += 1
		prefix_len = max(index, prefix_len)
	return prefix_len + 1

def str_to_precom(inp_str, n):
	precom = [[] for i in range(29)]
	[precom[ord(inp_str[i]) - ord('a')].append(i) for i in range(n)]
	return precom

