def get_pref_sizes(s, names):
	alpha_prefix = dict()
	for code in range(26):
		c = chr(code + ord('a'))
		alpha_prefix[c] = [0] * len(s)
	alpha_prefix[s[0]][0] = 1
	for (ind, ch) in enumerate(s[1:], start=1):
		for (key, _) in alpha_prefix.items():
			alpha_prefix[key][ind] = alpha_prefix[key][ind - 1]
			if key == ch:
				alpha_prefix[key][ind] += 1
	for name in names:
		letter_cnt = dict()
		for code in range(26):
			c = chr(code + ord('a'))
			letter_cnt[c] = 0
		for ch in name:
			letter_cnt[ch] += 1
		(left, right) = (0, len(s) + 1)
		while left + 1 < right:
			mid = (left + right) // 2
			if is_enough(mid, alpha_prefix, letter_cnt):
				right = mid
			else:
				left = mid
		print(right)
