from collections import Counter

def build_map(text):
	m = {}
	for (i, t) in enumerate(text):
		if t not in m:
			m[t] = []
		m[t].append(i)
	return m

def calc(text_map, name):
	c = Counter(name)
	ans = 0
	for (letter, count) in c.items():
		ans = max(ans, text_map[letter][count - 1])
	return ans + 1

def main():
	_ = input()
	s = input()
	s_map = build_map(s)
	m = int(input())
	for _ in range(m):
		name = input()
		print(calc(s_map, name))
main()
